def get_total_number_of_sequences(m, n):
    # Edge case: if n == 1, each sequence is just a single number from 1 to m
    if n == 1:
        return m

    # Initialize the count of sequences ending with each number for the first position
    # For position 1, any number from 1 to m can start the sequence
    prev_counts = [1] * (m + 1)  # Index 0 unused

    for _ in range(2, n + 1):
        curr_counts = [0] * (m + 1)
        for num in range(1, m + 1):
            # For each number, sum counts of previous numbers that satisfy the condition:
            # previous number >= ceil(num/2)
            start = (num + 1) // 2  # integer division for ceiling
            for prev_num in range(start, m + 1):
                curr_counts[num] += prev_counts[prev_num]
        prev_counts = curr_counts

    # Total sequences are sum over all possible ending numbers
    return sum(prev_counts[1:])
