SELECT cm.Maker, ml.Model 
FROM car_makers cm 
JOIN model_list ml ON cm.Id = ml.Maker;

SELECT Country, COUNT(*) AS Singer_Count
FROM singer
GROUP BY Country;

SELECT Song_Name
FROM singer
WHERE Age > (SELECT AVG(Age) FROM singer);

SELECT PetType, AVG(weight) AS average_weight
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) AS Average_Weight
FROM Pets
GROUP BY PetType;

SELECT Fname, Age
FROM Student
WHERE StuID IN (
    SELECT StuID FROM Has_Pet WHERE PetID IN (
        SELECT PetID FROM Pets WHERE PetType = 'dog'
    )
)
AND StuID NOT IN (
    SELECT StuID FROM Has_Pet WHERE PetID IN (
        SELECT PetID FROM Pets WHERE PetType = 'cat'
    )
);

SELECT COUNT(*) AS NumberOfPets
FROM Has_Pet
WHERE StuID IN (SELECT StuID FROM Student WHERE Age > 20);

SELECT Year, AVG(Weight) AS AverageWeight
FROM cars_data
GROUP BY Year;

SELECT h.StuID, COUNT(h.PetID) AS PetCount
FROM Has_Pet h
GROUP BY h.StuID;

SELECT StuID, COUNT(PetID) AS PetCount
FROM Has_Pet
GROUP BY StuID;

SELECT PetType, AVG(pet_age) AS average_age, MAX(pet_age) AS maximum_age
FROM Pets
GROUP BY PetType;

SELECT COUNT(*) 
FROM cars_data 
WHERE Accelerate > (SELECT MAX(Horsepower) FROM cars_data);

SELECT COUNT(*) 
FROM cars_data AS c1
WHERE c1.Accelerate > (
    SELECT MAX(c2.Horsepower)
    FROM cars_data AS c2
);

SELECT PetType, MAX(weight) AS MaxWeight 
FROM Pets 
GROUP BY PetType;

SELECT PetType, MAX(weight) AS MaxWeight
FROM Pets
GROUP BY PetType;

SELECT DISTINCT Year FROM cars_data WHERE Weight < 4000
UNION
SELECT DISTINCT Year FROM cars_data WHERE Weight > 3000;

SELECT COUNT(*) FROM (
    SELECT c.Country, COUNT(cm.Id) AS MakerCount
    FROM countries c
    LEFT JOIN car_makers cm ON c.ContId = cm.Country
    GROUP BY c.Country
) WHERE MakerCount > 2;

SELECT Country
FROM airlines
WHERE Airline = 'JetBlue Airways';

SELECT cm.Maker, ml.Model 
FROM car_makers cm 
JOIN model_list ml ON cm.Id = ml.Maker;

SELECT DISTINCT S.Fname, S.Age 
FROM Student S 
JOIN Has_Pet HP ON S.StuID = HP.StuID;

SELECT DISTINCT Fname, Age
FROM Student
WHERE StuID IN (SELECT StuID FROM Has_Pet);

SELECT h.StuID, COUNT(h.PetID) AS PetCount
FROM Has_Pet h
GROUP BY h.StuID;

SELECT AVG(Age) AS AverageAge
FROM Student
WHERE StuID NOT IN (SELECT DISTINCT StuID FROM Has_Pet);

SELECT AVG(CAST(MPG AS REAL)) AS Average_MPG
FROM cars_data
WHERE Cylinders = 4;

SELECT Cylinders, MAX(Accelerate) AS MaxAccelerate
FROM cars_data
GROUP BY Cylinders;

SELECT DISTINCT cn.Model
FROM car_names cn
JOIN cars_data cd ON cn.MakeId = cd.Id
WHERE cn.Make IN (
    SELECT Id FROM car_makers WHERE Maker = 'General Motors'
) OR cd.Weight > 3500;

SELECT Horsepower
FROM cars_data
WHERE Accelerate = (SELECT MAX(Accelerate) FROM cars_data) LIMIT 1;
